<section class="admin-page-head"><div><p class="admin-kicker">ACCESO</p><h1>Usuarios</h1><p>Administra identidades, estados y privilegios sin eliminar historial.</p></div><?php if ($capabilities['users.create'] ?? false): ?><a class="admin-primary-button" href="/admin/users/create">+ Nuevo usuario</a><?php endif ?></section>
